"use strict";(globalThis.webpackChunkgolden_goose||=[]).push([[756],{756(e){e.exports=JSON.parse('{"id":"microsoft-sc-200","vendor":"Microsoft","code":"SC-200","name":"Microsoft Certified: Security Operations Analyst Associate","fullLength":50,"minutes":100,"passPercent":70,"readinessPercent":80,"sectioned":false,"note":"Microsoft scores SC-200 on a 1\u20131000 scale with 700 to pass. This practice exam reports a straight percentage; treat 80% as your readiness bar. Questions follow the skills measured as of October 21, 2026. The real exam can include case studies and labs, which this practice exam doesn\'t simulate.","domains":[{"id":"OPS","name":"Manage a security operations environment","weight":"40\u201345%"},{"id":"INC","name":"Respond to security incidents","weight":"35\u201340%"},{"id":"HNT","name":"Perform threat hunting","weight":"20\u201325%"}],"groups":{},"questions":[{"id":"sc200-1","domain":"OPS","stem":"The SOC lead wants an email whenever a new high-severity incident is created in Microsoft Defender XDR. Where should this be configured?","options":["A mail flow rule in the Exchange admin center","A Microsoft Sentinel workbook with a scheduled export","An Azure Monitor action group on the Log Analytics workspace","An email notification rule for incidents in Defender XDR"],"answer":[3],"explanation":"Defender XDR\'s email notification settings let you create rules that email recipients about new incidents, filtered by severity and device group, and also about response actions and threat analytics reports."},{"id":"sc200-2","domain":"OPS","stem":"A recurring Defender XDR alert is a known false positive caused by an approved admin tool. What should the analyst configure so it stops creating noise?","options":["A live response session","A new device group","An alert tuning rule","A custom detection rule"],"answer":[2],"explanation":"Alert tuning rules (formerly suppression rules) hide or automatically resolve alerts that match conditions you specify, such as a specific file or command line, reducing noise from known benign activity."},{"id":"sc200-3","domain":"OPS","stem":"Which Microsoft Defender for Endpoint advanced feature must be turned on before analysts can open remote shell sessions on devices?","options":["Custom network indicators","Tamper protection","Live response","Web content filtering"],"answer":[2],"explanation":"The Live response advanced feature enables remote shell connections to devices. Separate settings control live response for servers and running unsigned scripts."},{"id":"sc200-4","domain":"OPS","stem":"An organization wants to block a known malicious file hash on all Defender for Endpoint devices. What should it create?","options":["A device group with full automation","An attack surface reduction rule","A file indicator with a block action","An alert tuning rule for the hash"],"answer":[2],"explanation":"Indicators of compromise in Defender for Endpoint let you allow, warn, or block files by hash, as well as IP addresses, URLs, domains, and certificates. The Allow or block file advanced feature must be on to block files."},{"id":"sc200-5","domain":"OPS","stem":"Before enforcing attack surface reduction (ASR) rules, a team wants to see which apps would be affected without blocking anything. Which mode should it use?","options":["Audit mode","Block mode","Disabled mode","Warn mode"],"answer":[0],"explanation":"Audit mode logs what an ASR rule would have blocked, so you can review impact and add exclusions before switching to Block. Warn mode blocks but lets users override."},{"id":"sc200-6","domain":"OPS","stem":"Which ASR rule helps stop Office macros from launching other processes, a common malware technique?","options":["Use advanced protection against ransomware","Block persistence through WMI event subscription","Block Office apps from creating child processes","Block untrusted and unsigned processes that run from USB"],"answer":[2],"explanation":"The Office child-process rule prevents Word, Excel, and other Office apps from spawning processes such as PowerShell or cmd, which malicious macros often do."},{"id":"sc200-7","domain":"OPS","stem":"What does setting a Defender for Endpoint device group\'s automation level to \\"Full \u2013 remediate threats automatically\\" do?","options":["Remediation actions run without waiting for approval","Automated investigations are turned off for the group","Devices are isolated whenever any alert is raised","Every alert is escalated to a human analyst first"],"answer":[0],"explanation":"With full automation, automated investigation and response (AIR) applies remediation actions automatically. Semi-automated levels require approval for some or all actions, and \\"No automated response\\" turns AIR off for the group."},{"id":"sc200-8","domain":"OPS","stem":"Why create device groups in Defender for Endpoint?","options":["To join devices to Microsoft Entra ID automatically","To set automation levels and access per set of devices","To license Defender for Endpoint per department","To store device logs in separate Sentinel workspaces"],"answer":[1],"explanation":"Device groups let you assign different automation levels and, with role-based access control, limit which analysts can see and act on which devices \u2014 for example, keeping servers on semi-automation."},{"id":"sc200-9","domain":"OPS","stem":"Which Defender for Endpoint setting restricts a Tier 1 analyst to viewing and responding to alerts only for devices in the retail branch offices?","options":["An ASR rule exclusion for retail devices","A global Security Reader role in Entra ID","A custom role scoped to the retail device group","A tamper protection exception for analysts"],"answer":[2],"explanation":"Defender for Endpoint RBAC (or Defender XDR unified RBAC) assigns roles with specific permissions to user groups and scopes them to device groups, so analysts only access the devices they\'re responsible for."},{"id":"sc200-10","domain":"OPS","stem":"What does automated investigation and response (AIR) in Defender XDR do when an alert fires?","options":["Creates a new Sentinel analytics rule for the same pattern","Resets the passwords of all users in the organization","Investigates evidence and recommends or takes remediation actions","Sends the alert to Microsoft for manual analysis"],"answer":[2],"explanation":"AIR examines alerts and related entities, determines verdicts such as malicious or clean, and recommends or applies remediation actions, which appear in the Action center for review or approval."},{"id":"sc200-11","domain":"OPS","stem":"Where do analysts approve or reject pending remediation actions from automated investigations?","options":["The Microsoft Entra admin center audit log","The Azure Activity log","The Sentinel workbook gallery","The Action center in the Defender portal"],"answer":[3],"explanation":"The Action center lists pending and completed remediation actions across devices, email, and identities, where analysts can approve, reject, or undo them."},{"id":"sc200-12","domain":"OPS","stem":"What does automatic attack disruption in Defender XDR do?","options":["Automatically contains compromised users and devices","Shuts down every device in the tenant during an incident","Deletes all email that arrives from external domains","Rolls back the Sentinel workspace to an earlier state"],"answer":[0],"explanation":"Attack disruption correlates signals to identify high-confidence attacks such as ransomware or business email compromise and automatically takes containment actions, like disabling a user or containing a device, to limit damage while analysts investigate."},{"id":"sc200-13","domain":"OPS","stem":"Which configuration lets automatic attack disruption disable a compromised on-premises Active Directory user account?","options":["A Sentinel playbook triggered by every alert","Defender for Identity with an action account","Tamper protection enabled on domain controllers","An Entra Connect writeback rule for disabled users"],"answer":[1],"explanation":"Disabling on-premises AD accounts is done through Defender for Identity, which uses its action account (by default the sensor\'s LocalSystem identity) to perform the action in Active Directory."},{"id":"sc200-14","domain":"OPS","stem":"A critical service account must never be disabled automatically by attack disruption. What should you configure?","options":["A lower severity for all alerts involving the account","Tamper protection on the account\'s sign-in device","A separate device group with no automated response","An exclusion for that account in attack disruption settings"],"answer":[3],"explanation":"You can exclude specific user accounts (and devices) from automated containment actions, so attack disruption won\'t act on them while still raising incidents."},{"id":"sc200-15","domain":"OPS","stem":"What\'s the main difference between Microsoft Sentinel automation rules and playbooks?","options":["Automation rules run Python code; playbooks run KQL queries","They\'re the same feature with different names in different portals","Automation rules triage; playbooks run Logic Apps workflows","Playbooks can only close incidents; automation rules call external APIs"],"answer":[2],"explanation":"Automation rules handle common triage tasks \u2014 assigning owners, changing severity or status, adding tags \u2014 and can run playbooks. Playbooks are Azure Logic Apps workflows for more complex actions, such as calling external systems."},{"id":"sc200-16","domain":"OPS","stem":"Every new incident from a specific analytics rule should be assigned to the Tier 2 queue and tagged \\"phishing\\". What\'s the simplest approach?","options":["A summary rule","A Logic Apps playbook","A scheduled KQL job","An automation rule"],"answer":[3],"explanation":"Automation rules can assign incidents, change severity or status, and add tags without building a Logic Apps workflow. Playbooks are better for tasks that need external actions."},{"id":"sc200-17","domain":"OPS","stem":"A playbook must automatically disable a user in Microsoft Entra ID when an incident is created. Which trigger should the playbook use?","options":["An HTTP request from the analyst\'s browser","A recurrence trigger every five minutes","A Microsoft Sentinel incident trigger","A SharePoint file creation trigger"],"answer":[2],"explanation":"Playbooks for incident response use the Microsoft Sentinel incident trigger and are run from automation rules, giving the playbook the incident\'s entities to act on."},{"id":"sc200-18","domain":"OPS","stem":"Which permission does Microsoft Sentinel need before an automation rule can run a playbook in a given resource group?","options":["Global Administrator rights for the automation rule\'s creator","An Entra ID P2 license assigned to the playbook","Owner rights on every subscription in the tenant","Playbook permissions granted to Sentinel for that resource group"],"answer":[3],"explanation":"Sentinel uses a service account that needs the Microsoft Sentinel Automation Contributor role on the playbook\'s resource group, which you grant from Sentinel\'s settings, before automation rules can run playbooks there."},{"id":"sc200-19","domain":"OPS","stem":"An analyst must view incidents and data in Microsoft Sentinel and update incident status and assignment, but not create analytics rules. Which built-in role fits?","options":["Microsoft Sentinel Contributor","Logic App Contributor","Microsoft Sentinel Responder","Microsoft Sentinel Reader"],"answer":[2],"explanation":"Responder can view data and manage incidents (assign, change status, comment). Reader can only view, and Contributor can also create and edit analytics rules, workbooks, and other content."},{"id":"sc200-20","domain":"OPS","stem":"Which Microsoft Sentinel role lets a user run playbooks manually but not create or edit them?","options":["Logic App Contributor","Microsoft Sentinel Reader","Microsoft Sentinel Playbook Operator","Microsoft Sentinel Automation Contributor"],"answer":[2],"explanation":"Playbook Operator allows listing and running playbooks. Logic App Contributor is needed to create or edit them, and Automation Contributor is assigned to Sentinel itself so automation rules can run playbooks."},{"id":"sc200-21","domain":"OPS","stem":"In the Microsoft Sentinel platform, what\'s the purpose of the data lake tier?","options":["Low-cost, long-term retention for analysis","Hosting workbooks for executive dashboards","Storing playbooks and automation rule definitions","Real-time detection rules that run every minute"],"answer":[0],"explanation":"The data lake tier stores large volumes of security data cost-effectively for up to 12 years, for KQL exploration, jobs, and notebooks. The analytics tier supports real-time detections, alerting, and interactive hunting."},{"id":"sc200-22","domain":"OPS","stem":"High-volume firewall logs are rarely used for detections but must be kept for two years for investigations. Where should they be stored to reduce cost?","options":["A Sentinel watchlist","The data lake tier","The analytics tier","An Advanced Hunting table"],"answer":[1],"explanation":"Sending low-value, high-volume logs to the data lake tier keeps them queryable for investigations at a much lower cost than the analytics tier, which is meant for data used in real-time detection."},{"id":"sc200-23","domain":"OPS","stem":"How long does Defender XDR Advanced Hunting keep data in its own tables by default?","options":["2 years","30 days","7 days","180 days"],"answer":[1],"explanation":"Defender XDR Advanced Hunting tables keep 30 days of data. To keep it longer, stream or connect the data to Microsoft Sentinel and configure retention in the analytics and data lake tiers."},{"id":"sc200-24","domain":"OPS","stem":"What happens to data stored in the analytics tier when the Sentinel data lake is enabled?","options":["It\'s converted into watchlists","It\'s moved to a separate subscription","It\'s deleted after 24 hours to save cost","It\'s mirrored to the lake tier"],"answer":[3],"explanation":"Data in the analytics tier is mirrored to the lake tier, preserving a single copy that can be retained long term and analyzed with KQL jobs and notebooks."},{"id":"sc200-25","domain":"OPS","stem":"A SOC manager wants a dashboard of incident trends and data source health in Microsoft Sentinel. What should they create?","options":["A playbook","A workbook","A watchlist","An automation rule"],"answer":[1],"explanation":"Workbooks provide interactive visualizations of Sentinel data. Many are available from the Content hub and can be customized with KQL queries and parameters."},{"id":"sc200-26","domain":"OPS","stem":"What do SOC optimization recommendations in Microsoft Sentinel help with?","options":["Writing incident reports for executives","Assigning licenses to new SOC staff","Reducing cost and closing coverage gaps","Resetting analysts\' passwords on a schedule"],"answer":[2],"explanation":"SOC optimization analyzes your data and detections to recommend changes, such as moving unused data to cheaper tiers or adding detections for threats relevant to your environment."},{"id":"sc200-27","domain":"OPS","stem":"Which connector should be used to collect Windows security events from Azure VMs into Microsoft Sentinel today?","options":["Common Event Format via AMA","Syslog via AMA","Windows Security Events via AMA","Security Events via legacy agent"],"answer":[2],"explanation":"Windows Security Events via AMA uses the Azure Monitor Agent with data collection rules (DCRs). The legacy Log Analytics agent is retired. Syslog and CEF connectors are for Linux and network devices."},{"id":"sc200-28","domain":"OPS","stem":"With the Azure Monitor Agent, what defines which Windows events are collected and where they\'re sent?","options":["A Sentinel watchlist","A data collection rule (DCR)","A workbook parameter","A Group Policy logon script"],"answer":[1],"explanation":"Data collection rules specify the data sources, such as event sets or XPath queries, the destination workspace, and optional transformations. DCRs are associated with the machines whose data they collect."},{"id":"sc200-29","domain":"OPS","stem":"To reduce cost, a team wants to collect only Windows event IDs 4624 and 4625 from servers. How should they configure the AMA connector?","options":["Use an XPath query in the DCR","Select the \\"All Security Events\\" event set","Add the event IDs to a Sentinel watchlist","Set the workspace retention to seven days"],"answer":[0],"explanation":"Data collection rules can use XPath queries to collect specific event IDs. The predefined event sets \u2014 All, Common, and Minimal \u2014 are an alternative when you don\'t need that precision."},{"id":"sc200-30","domain":"OPS","stem":"Hundreds of on-premises workstations can\'t run agents. How can their Windows security events reach Microsoft Sentinel?","options":["Configure Syslog on each Windows workstation","Export them weekly to a CSV in SharePoint","Install Sentinel directly on each workstation","Forward them with WEF to an AMA collector"],"answer":[3],"explanation":"Windows Event Forwarding sends events from many devices to a collector server. With AMA installed on the collector (Azure Arc\u2013enabled if on-premises), a DCR collects the ForwardedEvents channel into Sentinel."},{"id":"sc200-31","domain":"OPS","stem":"A firewall can send logs only in Common Event Format (CEF) over Syslog. What\'s needed to ingest them with CEF via AMA?","options":["A Windows collector configured with WEF subscriptions","A Logic Apps playbook polling the firewall API","A direct connection from the firewall to the workspace","A Linux log forwarder running AMA and a Syslog daemon"],"answer":[3],"explanation":"CEF via AMA uses a Linux machine with rsyslog or syslog-ng and the Azure Monitor Agent to receive the firewall\'s Syslog messages and forward them, parsed into the CommonSecurityLog table."},{"id":"sc200-32","domain":"OPS","stem":"Which table stores events ingested through the CEF via AMA connector?","options":["ThreatIntelIndicators","CommonSecurityLog","SecurityEvent","Syslog"],"answer":[1],"explanation":"CEF events are parsed into CommonSecurityLog. Plain Syslog lands in Syslog, Windows security events in SecurityEvent, and threat indicators in ThreatIntelIndicators."},{"id":"sc200-33","domain":"OPS","stem":"How should an organization make sure Azure activity logs from all its subscriptions reach Microsoft Sentinel, including new subscriptions?","options":["Create a watchlist of subscription IDs to collect from","Enable the activity log manually in each portal session","Assign an Azure Policy that configures diagnostic settings","Install the Azure Monitor Agent on every virtual machine"],"answer":[2],"explanation":"The Azure Activity connector uses Azure Policy to create diagnostic settings that stream activity logs to the workspace, and a policy assignment at a management group also covers new subscriptions."},{"id":"sc200-34","domain":"OPS","stem":"How can threat indicators from a partner\'s STIX/TAXII feed be ingested into Microsoft Sentinel?","options":["With the TAXII threat intelligence connector","By adding them to an ASR rule exclusion list","By uploading them to a Sentinel workbook","With the Windows Security Events via AMA connector"],"answer":[0],"explanation":"The TAXII connector pulls STIX indicators from TAXII 2.x servers. Indicators can also be uploaded through the threat intelligence upload API or imported from files, and they\'re used by threat intelligence analytics rules."},{"id":"sc200-35","domain":"OPS","stem":"A custom application sends JSON logs that don\'t match any built-in table. How should they be stored in Sentinel?","options":["In the AzureActivity table under a new category","In the SecurityEvent table, renamed for the app","In a custom _CL table, via a DCR","In a watchlist that\'s refreshed every hour"],"answer":[2],"explanation":"Custom tables, whose names end in _CL, can be created in the workspace and fed through a data collection rule and the Logs Ingestion API, optionally transforming the data on the way in."},{"id":"sc200-36","domain":"OPS","stem":"Which connector type should you choose for Microsoft 365 Defender, Entra ID, and other Microsoft sources that have built-in integrations?","options":["CEF via AMA through a Linux forwarder","Windows Event Forwarding to a collector","A custom table populated by a playbook","Service-to-service connectors"],"answer":[3],"explanation":"Microsoft sources usually have service-to-service connectors, installed as solutions from the Content hub, that need only permissions and a few clicks \u2014 no agents or forwarders."},{"id":"sc200-37","domain":"OPS","stem":"In Defender XDR, how do you turn an Advanced Hunting query into a detection that creates alerts?","options":["Save it as a custom detection","Add it to a device group","Pin it to a Sentinel workbook","Export it to a CSV file"],"answer":[0],"explanation":"From Advanced Hunting, you can create a custom detection rule from a query, set its frequency, alert details, impacted entities, and automated actions on matching devices, users, or files."},{"id":"sc200-38","domain":"OPS","stem":"Which columns must a Defender XDR custom detection query typically return so alerts can be created and linked to entities?","options":["Only the alert title and severity text","The analyst\'s user principal name","A playbook name and a workspace ID","Timestamp and an entity or event identifier"],"answer":[3],"explanation":"Custom detection queries need to return a Timestamp and identifying columns, such as DeviceId and ReportId, so the service can build alerts and map affected entities."},{"id":"sc200-39","domain":"OPS","stem":"A Defender XDR custom detection rule must catch ransomware behavior as quickly as possible. Which frequency setting fits?","options":["Every 24 hours","Every 3 hours","Every 12 hours","Continuous (NRT)"],"answer":[3],"explanation":"Custom detections can run continuously (NRT) for supported queries, or on schedules such as every 1, 3, 12, or 24 hours. Continuous rules raise alerts as matching events arrive."},{"id":"sc200-40","domain":"OPS","stem":"Which Microsoft Sentinel analytics rule type runs about every minute for fast detection of critical events?","options":["Near-real-time (NRT)","Machine learning behavior analytics","Scheduled","Threat intelligence"],"answer":[0],"explanation":"NRT rules run every minute over recently ingested data with a short lookback, for rapid detection. Scheduled rules run on a configurable interval, such as every 5 minutes to every 14 days."},{"id":"sc200-41","domain":"OPS","stem":"A scheduled analytics rule runs every hour and looks back over the past hour. What setting groups multiple matching results into one incident?","options":["Alert grouping settings","A watchlist of related entities","The rule\'s query frequency setting","The workspace data retention setting"],"answer":[0],"explanation":"Incident settings let you group alerts into a single incident, for example when entities match, within a time window, reducing duplicate incidents."},{"id":"sc200-42","domain":"OPS","stem":"Which analytics rule type matches your ingested logs against threat indicators automatically, without writing a query?","options":["Fusion multistage detection","Scheduled query","Near-real-time (NRT)","Threat intelligence"],"answer":[3],"explanation":"The Microsoft Defender Threat Intelligence analytics rule matches Microsoft-generated indicators against your logs. Indicator-matching rules from Content hub templates match your own imported indicators."},{"id":"sc200-43","domain":"OPS","stem":"What does entity mapping in a Sentinel analytics rule do?","options":["Maps each rule to the analyst who created it","Assigns a MITRE technique to the workspace","Links each alert to a specific Logic Apps playbook","Identifies accounts, hosts, and IPs in results"],"answer":[3],"explanation":"Entity mapping tells Sentinel which query columns represent entities such as accounts, hosts, IP addresses, and files, enabling the investigation graph, entity pages, and correlation across alerts."},{"id":"sc200-44","domain":"OPS","stem":"How can a SOC see which attacker techniques its active detections cover and where gaps exist?","options":["The MITRE ATT&CK view in Microsoft Sentinel","The Defender for Endpoint device inventory","The Entra ID sign-in logs workbook","The Azure subscription cost analysis view"],"answer":[0],"explanation":"Sentinel\'s MITRE ATT&CK page maps active and available analytics rules and hunting queries to tactics and techniques, highlighting coverage gaps."},{"id":"sc200-45","domain":"OPS","stem":"Where in an analytics rule can you record which MITRE ATT&CK tactics and techniques it detects?","options":["In its tactics and techniques settings","In the rule\'s playbook connection","In the workspace\'s diagnostic settings","In the data connector\'s configuration"],"answer":[0],"explanation":"Each analytics rule can be tagged with ATT&CK tactics and techniques, which feed the coverage view and appear on resulting alerts and incidents."},{"id":"sc200-46","domain":"OPS","stem":"What are anomalies in Microsoft Sentinel?","options":["Incidents closed as false positives","Analytics rules written entirely by analysts","Watchlists of known malicious IP addresses","ML-based detections that flag unusual behavior"],"answer":[3],"explanation":"Anomaly rules use built-in machine learning to identify unusual activity, such as atypical sign-ins or data volumes. They write to the Anomalies table and can be tuned or run in flighting mode before production."},{"id":"sc200-47","domain":"OPS","stem":"What can you adjust in a built-in Sentinel anomaly rule to reduce noise without disabling it?","options":["Its connector, by switching to a watchlist","Its threshold parameters, by duplicating the rule","Its source code, by editing the ML model","Its MITRE mapping, by deleting tactics"],"answer":[1],"explanation":"You can duplicate an anomaly rule, adjust its parameters such as thresholds, and run the copy in flighting mode alongside the production rule to compare results before switching."},{"id":"sc200-48","domain":"OPS","stem":"Which analytics rule type in Sentinel correlates low-fidelity alerts from multiple products to detect multistage attacks?","options":["Threat intelligence indicator matching","Near-real-time scheduled queries","Fusion multistage attack detection","Microsoft security incident creation"],"answer":[2],"explanation":"Fusion uses machine learning to correlate anomalous behaviors and suspicious activities across products into high-fidelity incidents representing multistage attacks."},{"id":"sc200-49","domain":"OPS","stem":"Your Sentinel workspace is connected to the Defender portal. What\'s true about Defender XDR incidents?","options":["They can be viewed only in the Azure portal afterward","They\'re synchronized and managed in the unified Defender portal","They must be recreated manually as Sentinel incidents","They\'re deleted from Defender when Sentinel ingests them"],"answer":[1],"explanation":"With Sentinel in the Defender portal, incidents from Sentinel and Defender XDR are correlated and managed in a single queue, and their status stays synchronized."},{"id":"sc200-50","domain":"OPS","stem":"What\'s the purpose of summary rules in Microsoft Sentinel?","options":["To summarize each incident in plain language for executives","To compress playbook run history into one log entry","To merge two workspaces into a single workspace","To aggregate data into a smaller table on a schedule"],"answer":[3],"explanation":"Summary rules run scheduled KQL aggregations over detailed or verbose data, including data in low-cost tiers, and write the results to a custom table in the analytics tier for faster, cheaper queries and detections."},{"id":"sc200-51","domain":"OPS","stem":"What\'s a watchlist in Microsoft Sentinel used for?","options":["A schedule for running analytics rules","A dashboard of open incidents by severity","A list of analysts assigned to on-call shifts","A set of reference data, like VIP users"],"answer":[3],"explanation":"Watchlists hold reference data imported from files \u2014 such as VIP accounts, terminated employees, or high-value assets \u2014 that queries and rules can join with using the _GetWatchlist function."},{"id":"sc200-52","domain":"INC","stem":"An analyst needs to find every mailbox that received a phishing email from a specific sender in the last week and remove it. Which tool fits best?","options":["Content explorer in Microsoft Purview","The Defender for Endpoint device timeline","Threat Explorer in Defender for Office 365","The Exchange message trace in Outlook"],"answer":[2],"explanation":"Threat Explorer (Explorer) lets analysts search delivered email by sender, subject, or URL across mailboxes and take actions such as soft delete or move to junk on the results."},{"id":"sc200-53","domain":"INC","stem":"A message is found to be malicious hours after it was delivered. Which Defender for Office 365 feature can remove it from mailboxes automatically?","options":["Zero-hour auto purge (ZAP)","Attack simulation training","Safe Links time-of-click checks","Mail flow rule journaling"],"answer":[0],"explanation":"ZAP retroactively moves or removes delivered messages that are later identified as spam, phishing, or malware, based on updated verdicts."},{"id":"sc200-54","domain":"INC","stem":"A user clicked a link in a phishing email. Which Advanced Hunting table shows Safe Links click events?","options":["EmailEvents","UrlClickEvents","IdentityLogonEvents","DeviceFileEvents"],"answer":[1],"explanation":"UrlClickEvents records Safe Links clicks from email, Teams, and Office apps, including whether the click was allowed or blocked. EmailEvents records message delivery."},{"id":"sc200-55","domain":"INC","stem":"What can automatic attack disruption do during a business email compromise attack?","options":["Disable the compromised user account automatically","Delete the organization\'s entire mail database","Block all outbound email from the tenant","Reset the domain\'s MX records to Microsoft"],"answer":[0],"explanation":"For BEC and adversary-in-the-middle phishing, attack disruption can automatically disable or contain the compromised user so the attacker can\'t keep using the session, while the incident is investigated."},{"id":"sc200-56","domain":"INC","stem":"A Microsoft Purview DLP alert appears in a Defender XDR incident alongside a suspicious sign-in. Why is it useful there?","options":["It changes the DLP policy to block mode automatically","It\'s correlated with other signals for one investigation","DLP alerts can only be closed from the Defender portal","Defender XDR automatically deletes the shared file"],"answer":[1],"explanation":"Purview DLP and Insider Risk Management alerts flow into Defender XDR, where they\'re correlated with identity, device, and email signals into incidents so analysts see the full story in one place."},{"id":"sc200-57","domain":"INC","stem":"An Insider Risk Management alert in the Defender portal shows a user\'s name as a pseudonym. Why?","options":["The user\'s account was deleted from Entra ID","The alert came from a guest account in another tenant","IRM pseudonymization protects user privacy during triage","Defender XDR always hides names for every alert type"],"answer":[2],"explanation":"Insider Risk Management can show pseudonymized user names to protect privacy, and only users with the right IRM permissions can see the real identities."},{"id":"sc200-58","domain":"INC","stem":"Microsoft Defender for Cloud raises an alert that a storage account was accessed from a Tor exit node. Where can the analyst investigate it alongside other alerts?","options":["In the Entra ID sign-in logs only","In the Purview compliance score view","Only in the storage account\'s access keys page","In the Defender portal\'s incident queue"],"answer":[3],"explanation":"Defender for Cloud workload protection alerts are integrated into Defender XDR, so they appear in correlated incidents in the Defender portal along with alerts from other workloads."},{"id":"sc200-59","domain":"INC","stem":"Defender for Servers flags suspicious PowerShell on an Azure VM. Which is a reasonable first response action?","options":["Delete the VM\'s resource group to stop the attack quickly","Investigate it and isolate the VM with Defender for Endpoint","Disable Defender for Cloud on the subscription to reduce noise","Change the VM size so the process restarts"],"answer":[1],"explanation":"Defender for Servers includes Defender for Endpoint, so analysts can investigate the process tree and isolate the machine while they investigate. Deleting resources destroys evidence."},{"id":"sc200-60","domain":"INC","stem":"Defender for Cloud Apps detects a third-party OAuth app with broad mail permissions that many users granted. What should the analyst do if it\'s malicious?","options":["Mark the app as a sanctioned app","Ban it and revoke its permissions","Increase the app\'s session timeout","Add the app to a device group"],"answer":[1],"explanation":"Defender for Cloud Apps app governance and OAuth app management let you ban an app and revoke its granted permissions, cutting off its access to user data."},{"id":"sc200-61","domain":"INC","stem":"Defender for Cloud Apps raises an \\"impossible travel\\" alert. What does it indicate?","options":["A user active in two distant places too quickly","An app that was installed on many devices at once","A user who booked travel through an unsanctioned app","A device that left the corporate network for travel"],"answer":[0],"explanation":"Impossible travel flags activity from the same user in geographically distant locations within a time shorter than travel between them would take, suggesting credential compromise."},{"id":"sc200-62","domain":"INC","stem":"Microsoft Entra ID Protection flags a user as high risk because of leaked credentials. After confirming compromise, what should the analyst do?","options":["Dismiss the user risk so the alert closes faster","Delete the user\'s mailbox and OneDrive immediately","Add the user to the Global Administrators group","Confirm compromise and require a password reset"],"answer":[3],"explanation":"Marking the user as confirmed compromised sets risk to high and feeds the detection models. Remediating with a secure password reset, revoking sessions, and reviewing activity follows. Dismissing risk is for false positives."},{"id":"sc200-63","domain":"INC","stem":"An analyst determines that a risky sign-in was actually the user traveling. What should they do in Entra ID Protection?","options":["Reset the user\'s MFA methods","Confirm the sign-in safe","Confirm the user compromised","Block the user permanently"],"answer":[1],"explanation":"Confirming a sign-in safe tells ID Protection the detection was a false positive, lowering risk and helping improve future detections."},{"id":"sc200-64","domain":"INC","stem":"Which immediate action invalidates a compromised user\'s existing sessions and refresh tokens in Microsoft Entra ID?","options":["Remove the user\'s license","Disable self-service password reset","Revoke the user\'s sessions","Change the user\'s display name"],"answer":[2],"explanation":"Revoking sessions invalidates refresh tokens so the attacker must sign in again, which, combined with a password reset and disabling the account if needed, cuts off access."},{"id":"sc200-65","domain":"INC","stem":"Defender for Identity raises an alert for \\"Suspected DCSync attack (replication of directory services)\\". What does it indicate?","options":["A user changed their password more than once a day","A non-DC requested replication of password hashes","A domain controller lost network connectivity briefly","An admin promoted a new domain controller normally"],"answer":[1],"explanation":"DCSync abuses replication permissions so a non-domain-controller requests directory data, including password hashes. Defender for Identity detects replication requests from machines that aren\'t DCs."},{"id":"sc200-66","domain":"INC","stem":"What are honeytoken accounts in Defender for Identity?","options":["Decoy accounts that alert when used","Accounts that store backup encryption keys","Service accounts exempt from all detections","Accounts that own every device group"],"answer":[0],"explanation":"Honeytokens are dormant decoy accounts that no legitimate process should use, so any authentication attempt with them raises an alert that likely signals an attacker."},{"id":"sc200-67","domain":"INC","stem":"Which Defender for Identity feature shows how an attacker could chain accounts and devices to reach a domain admin?","options":["Threat analytics reports","Lateral movement paths","Attack simulation training","Device timelines"],"answer":[1],"explanation":"Lateral movement paths show how sensitive accounts could be compromised through exposed credentials on intermediate devices, so they can be closed."},{"id":"sc200-68","domain":"INC","stem":"An alert raised by a Microsoft Sentinel analytics rule should be investigated in the Defender portal. What does the analyst use to explore related entities and alerts visually?","options":["The data connector\'s health page","The incident\'s attack story graph","The analytics rule\'s query editor","The workspace\'s usage and cost report"],"answer":[1],"explanation":"Incidents show an attack story with a graph of alerts, entities, and their relationships, which helps analysts understand scope and pivot to related activity."},{"id":"sc200-69","domain":"INC","stem":"An analyst closes a Sentinel incident that turned out to be an approved penetration test. Which classification fits?","options":["Undetermined","Benign positive","True positive","False positive"],"answer":[1],"explanation":"Benign positive means the detection was accurate \u2014 the suspicious activity happened \u2014 but it was expected or not malicious, such as an authorized test. False positive means the detection logic was wrong."},{"id":"sc200-70","domain":"INC","stem":"What\'s a good way to add context from an external ticketing system to every new Sentinel incident?","options":["A playbook run by an automation rule","An NRT rule that queries the ticket system","A workbook pinned to the incident queue","A watchlist refreshed by hand weekly"],"answer":[0],"explanation":"Playbooks can call external APIs, such as a ticketing or enrichment service, and write results back to the incident as comments or tasks when an automation rule triggers them."},{"id":"sc200-71","domain":"INC","stem":"How can embedded Microsoft Security Copilot help an analyst investigating an incident in the Defender portal?","options":["By summarizing it and suggesting guided response steps","By closing every incident older than seven days","By disabling detection rules that create noise","By replacing the need for analyst review entirely"],"answer":[0],"explanation":"Embedded Security Copilot can summarize incidents, recommend guided responses, analyze scripts and files, and help write KQL, while the analyst stays responsible for decisions."},{"id":"sc200-72","domain":"INC","stem":"An analyst finds an obfuscated PowerShell command in an alert. Which Security Copilot capability helps most?","options":["Automatic deletion of the device from Entra ID","A new ASR rule created without review","Script analysis explaining the command","An executive summary sent to the CISO"],"answer":[2],"explanation":"Security Copilot\'s script analysis explains what a script or command line does, including decoding obfuscation, so analysts can quickly judge whether it\'s malicious."},{"id":"sc200-73","domain":"INC","stem":"Which pattern best indicates lateral movement in an incident?","options":["An account signing in to many devices in turn","A user opening a file stored in their own OneDrive","A device installing a monthly Windows update","A single failed sign-in from a user\'s laptop"],"answer":[0],"explanation":"Lateral movement shows up as credentials being used to move between systems \u2014 for example, the same account logging on remotely to several devices in a short time, often with remote execution tools."},{"id":"sc200-74","domain":"INC","stem":"A multistage incident includes a phishing email, a malicious sign-in, and ransomware on two devices. What should the analyst do first?","options":["Lower the incident\'s severity","Contain affected users and devices","Close the email alert as resolved","Wait for all alerts to finish updating"],"answer":[1],"explanation":"With active ransomware, containment comes first \u2014 isolating devices and disabling or containing compromised accounts \u2014 to stop spread, followed by investigation, eradication, and recovery."},{"id":"sc200-75","domain":"INC","stem":"What does case management in the Defender portal let a SOC do?","options":["Group related incidents and track the work","Schedule ASR rules to turn on and off","Assign Microsoft 365 licenses to SOC members","Export workbooks to PowerPoint decks"],"answer":[0],"explanation":"Cases let analysts link related incidents, assign owners, track tasks and status, and keep notes and evidence together for longer or complex investigations."},{"id":"sc200-76","domain":"INC","stem":"An analyst needs to see the sequence of processes, network connections, and file changes on a device around an alert. Where should they look?","options":["The Action center history","The device timeline","The Secure Score page","The device group settings"],"answer":[1],"explanation":"The device timeline shows events on a device in chronological order \u2014 processes, files, network, registry, and logons \u2014 so analysts can reconstruct what happened before and after an alert."},{"id":"sc200-77","domain":"INC","stem":"A device is confirmed compromised, but analysts still need to investigate it remotely. Which action should they take?","options":["Isolate the device","Offboard the device","Delete the device record","Restart the device"],"answer":[0],"explanation":"Isolation disconnects the device from the network while keeping its connection to Defender for Endpoint, so investigation and live response can continue."},{"id":"sc200-78","domain":"INC","stem":"What\'s an investigation package in Defender for Endpoint?","options":["A collection of forensic data gathered from a device","An exported list of device group members","A license bundle for Defender for Endpoint P2","A playbook template for Sentinel automation"],"answer":[0],"explanation":"Collecting an investigation package gathers forensic artifacts such as autoruns, installed programs, network connections, processes, scheduled tasks, and event logs into a downloadable ZIP."},{"id":"sc200-79","domain":"INC","stem":"In a live response session, which command retrieves a suspicious file from the device for analysis?","options":["getfile","isolate","offboard","connect"],"answer":[0],"explanation":"getfile downloads a file from the device to the analyst. Other commands include run (for uploaded scripts), processes, and remediate."},{"id":"sc200-80","domain":"INC","stem":"An analyst wants to stop a running malicious process and quarantine its file across all devices where it appears. Which file action fits?","options":["Run antivirus scan only","Collect investigation package","Add a file indicator to allow","Stop and quarantine file"],"answer":[3],"explanation":"Stop and quarantine file kills the process and quarantines the file on affected devices. Adding a block indicator prevents it from running again."},{"id":"sc200-81","domain":"INC","stem":"Which device action prevents applications that aren\'t signed by Microsoft from running, while the device stays online?","options":["Restrict app execution","Collect investigation package","Run antivirus scan","Isolate device"],"answer":[0],"explanation":"Restrict app execution uses an application control policy that allows only Microsoft-signed files, limiting attacker tools while the device remains connected."},{"id":"sc200-82","domain":"INC","stem":"From a file\'s entity page in Defender for Endpoint, what can an analyst see?","options":["The user\'s Entra ID password history","The device\'s licensing and billing details","The analytics rules in Sentinel that use it","The devices it\'s on and its prevalence"],"answer":[3],"explanation":"File pages show prevalence in the organization and globally, devices where the file was observed, related alerts, and verdicts, and they offer actions such as stop and quarantine or submit for deep analysis."},{"id":"sc200-83","domain":"INC","stem":"A device was contained by automatic attack disruption. Where does the analyst release the containment after remediation?","options":["From the Azure subscription settings","From the device page or the Action center","From the Entra ID user\'s license page","From the Sentinel data connector page"],"answer":[1],"explanation":"Containment actions taken by attack disruption appear in the Action center and on the device page, where analysts can undo them \u2014 for example, releasing a contained device \u2014 once it\'s safe."},{"id":"sc200-84","domain":"INC","stem":"Which evidence verdict in an automated investigation means the entity needs analyst review?","options":["Remediated","Clean","Suspicious","No threats found"],"answer":[2],"explanation":"AIR assigns verdicts to evidence: malicious items are remediated (automatically or with approval), suspicious items need analyst review, and clean items need no action."},{"id":"sc200-85","domain":"INC","stem":"Why should an analyst run a deep analysis submission on an unknown executable?","options":["To upload it to the device\'s OneDrive","To detonate it in a sandbox","To reset the device that downloaded it","To permanently allow it on all devices"],"answer":[1],"explanation":"Deep analysis runs the file in a secure cloud sandbox and reports behaviors such as network connections, file changes, and registry modifications, helping determine whether it\'s malicious."},{"id":"sc200-86","domain":"INC","stem":"An analyst needs to see who accessed a sensitive SharePoint file over the past month. Which tool fits?","options":["Defender for Endpoint timeline","Microsoft Purview Audit","Content explorer","Threat analytics"],"answer":[1],"explanation":"Purview Audit records user and admin activities across Microsoft 365, including SharePoint file access events such as FileAccessed, searchable by user, activity, and date."},{"id":"sc200-87","domain":"INC","stem":"Which PowerShell cmdlet searches the unified audit log?","options":["Search-UnifiedAuditLog","Get-MessageTrace","Get-MgAuditLogSignIn","New-ComplianceSearch"],"answer":[0],"explanation":"Search-UnifiedAuditLog, run in Exchange Online PowerShell, queries the unified audit log. New-ComplianceSearch creates eDiscovery content searches, and Get-MessageTrace traces mail flow."},{"id":"sc200-88","domain":"INC","stem":"During an investigation, an analyst must find every mailbox containing an email with a specific malicious attachment name and preserve copies. Which tool fits?","options":["Defender for Endpoint live response","Microsoft Purview Audit search","Entra ID sign-in logs","eDiscovery content search"],"answer":[3],"explanation":"eDiscovery content search finds items across mailboxes, sites, and Teams by keywords and conditions, and its results can be exported or preserved with holds. Audit shows activities, not message content."},{"id":"sc200-89","domain":"INC","stem":"Which data source shows the Microsoft Graph API requests an app or user made, such as reading many mailboxes?","options":["Entra ID sign-in logs","Azure activity logs","Defender for Endpoint timelines","Microsoft Graph activity logs"],"answer":[3],"explanation":"Graph activity logs record HTTP requests made to Microsoft Graph, including the app, user, request URI, and response, which helps investigate data access by compromised apps or tokens. They\'re sent to a workspace through Entra diagnostic settings."},{"id":"sc200-90","domain":"INC","stem":"How do you make Microsoft Graph activity logs available for querying in Microsoft Sentinel?","options":["Install the Azure Monitor Agent on every Graph client","Enable them in Defender for Endpoint advanced features","Export them from Purview Audit to a watchlist","Send them to the workspace with Entra ID diagnostic settings"],"answer":[3],"explanation":"Graph activity logs are configured as a log category in Microsoft Entra diagnostic settings and stream into the MicrosoftGraphActivityLogs table in a Log Analytics workspace."},{"id":"sc200-91","domain":"INC","stem":"An attacker created an inbox rule forwarding a CFO\'s mail externally. How can an analyst find when the rule was created?","options":["Search the audit log for New-InboxRule activity","Review the Sentinel workspace usage report","Look in the Defender for Identity health page","Check the device timeline of the CFO\'s laptop"],"answer":[0],"explanation":"Inbox rule creation is audited as New-InboxRule (or Set-InboxRule) in Exchange, so a Purview Audit or Search-UnifiedAuditLog search shows who created it, when, and from which IP."},{"id":"sc200-92","domain":"INC","stem":"Which audit activity indicates that someone accessed mailbox items, which helps scope a business email compromise?","options":["SearchQueryInitiated","MailItemsAccessed","FileAccessed","UserLoggedIn"],"answer":[1],"explanation":"MailItemsAccessed records when mail data is accessed by mail protocols and clients, helping determine which messages an attacker could have read."},{"id":"sc200-93","domain":"INC","stem":"An analyst needs to find which mailboxes a compromised account sent emails to. Which Advanced Hunting table helps?","options":["EmailEvents","DeviceProcessEvents","IdentityDirectoryEvents","DeviceRegistryEvents"],"answer":[0],"explanation":"EmailEvents contains delivery and send events for email, including sender, recipients, subject, and delivery action, which helps scope phishing or BEC activity."},{"id":"sc200-94","domain":"INC","stem":"What\'s the advantage of investigating a threat in the Defender portal with unified Sentinel and Defender XDR data?","options":["Automatic closure of every low-severity incident","One place to correlate SIEM and XDR data","Lower licensing cost for every Microsoft product","No need to configure any data connectors"],"answer":[1],"explanation":"The unified security operations platform brings Sentinel SIEM data and Defender XDR data together, so analysts investigate incidents and run Advanced Hunting across both in one experience."},{"id":"sc200-95","domain":"INC","stem":"A Purview Audit search returns no results for activity from 200 days ago in an E3 tenant. Why?","options":["Purview Audit only covers Exchange events","Audit logging is off by default in E3","Search-UnifiedAuditLog only returns one day","Audit (Standard) keeps records for 180 days"],"answer":[3],"explanation":"Audit (Standard) retains records for 180 days. Longer retention needs Audit (Premium) or exporting records to a SIEM such as Microsoft Sentinel."},{"id":"sc200-96","domain":"INC","stem":"Which response is most appropriate after confirming a malicious inbox forwarding rule?","options":["Leave the rule in place to monitor the attacker","Disable auditing to stop new alerts","Delete the user\'s account and all their data","Remove it, reset the password, revoke sessions"],"answer":[3],"explanation":"Removing the rule stops exfiltration, and resetting the password and revoking sessions removes the attacker\'s access. Reviewing what was forwarded and sign-in activity helps scope the impact."},{"id":"sc200-97","domain":"HNT","stem":"Which Advanced Hunting table should you query to find processes created by powershell.exe on devices?","options":["EmailAttachmentInfo","IdentityLogonEvents","DeviceNetworkEvents","DeviceProcessEvents"],"answer":[3],"explanation":"DeviceProcessEvents records process creation, including command lines and parent processes. DeviceNetworkEvents records connections, IdentityLogonEvents records authentication, and EmailAttachmentInfo describes email attachments."},{"id":"sc200-98","domain":"HNT","stem":"Which table shows outbound connections from devices to a suspicious IP address?","options":["DeviceNetworkEvents","CloudAppEvents","DeviceFileEvents","DeviceRegistryEvents"],"answer":[0],"explanation":"DeviceNetworkEvents contains network connections and related events from devices, including remote IPs, ports, and the initiating process."},{"id":"sc200-99","domain":"HNT","stem":"Which table records file creation and modification on devices, such as a ransomware note being written?","options":["DeviceFileEvents","AlertInfo","DeviceRegistryEvents","DeviceLogonEvents"],"answer":[0],"explanation":"DeviceFileEvents records file creation, modification, renaming, and deletion on devices, along with the process responsible."},{"id":"sc200-100","domain":"HNT","stem":"Which table holds activities in cloud apps such as SharePoint, Exchange, and connected third-party apps?","options":["IdentityQueryEvents","CloudAppEvents","DeviceEvents","DeviceImageLoadEvents"],"answer":[1],"explanation":"CloudAppEvents contains activities from Microsoft 365 and other apps connected through Defender for Cloud Apps, such as file sharing and admin operations."},{"id":"sc200-101","domain":"HNT","stem":"Which KQL operator filters rows to those matching a condition?","options":["project","summarize","where","extend"],"answer":[2],"explanation":"where filters rows. project selects columns, summarize aggregates, and extend adds calculated columns."},{"id":"sc200-102","domain":"HNT","stem":"Which query counts failed sign-ins per account?","options":["... | extend count() by AccountName","... | project count() by AccountName","... | summarize count() by AccountName","... | take count() by AccountName"],"answer":[2],"explanation":"summarize aggregates rows into groups, so summarize count() by AccountName returns one row per account with its count. The other operators don\'t group rows."},{"id":"sc200-103","domain":"HNT","stem":"Which KQL expression limits results to the last seven days?","options":["where Timestamp < now(7d)","where Timestamp > ago(7d)","where Timestamp == today(-7)","where Timestamp in last(7d)"],"answer":[1],"explanation":"ago(7d) returns the time seven days before now, so filtering Timestamp greater than it keeps the last week of data."},{"id":"sc200-104","domain":"HNT","stem":"Why is the has operator often preferred over contains in KQL hunting queries?","options":["contains only works on numeric columns","has searches every table in the workspace at once","has is case sensitive, so it finds more matches","has matches indexed whole terms, so it\'s faster"],"answer":[3],"explanation":"has looks for whole terms and uses the term index, making it much faster on large tables. contains matches any substring, which is slower but catches partial words."},{"id":"sc200-105","domain":"HNT","stem":"A hunter wants to combine process events with network events for the same device and process. Which operator fits?","options":["render","join","top","union"],"answer":[1],"explanation":"join combines rows from two tables that share key values, such as DeviceId and process ID. union appends tables, render draws charts, and top returns the first rows by a column."},{"id":"sc200-106","domain":"HNT","stem":"What does threat analytics in Defender XDR provide?","options":["Benchmarks comparing your SOC staffing to peers","Reports on active threats and your exposure","A calendar of planned Windows updates","A list of every alert closed by analysts last month"],"answer":[1],"explanation":"Threat analytics reports describe current threats and actor campaigns, show related alerts and impacted assets in your environment, and list recommended mitigations and their status."},{"id":"sc200-107","domain":"HNT","stem":"A new threat analytics report covers a vulnerability being exploited in the wild. What should the analyst check first?","options":["Whether the report\'s author is a Microsoft employee","Whether the report includes a video walkthrough","How many other customers read the report","Whether any assets are exposed or affected"],"answer":[3],"explanation":"Threat analytics shows your organization\'s exposure \u2014 impacted assets, related alerts, and mitigation status \u2014 so analysts can prioritize patching and hunting."},{"id":"sc200-108","domain":"HNT","stem":"What does a hunting graph with blast radius analysis help an analyst understand?","options":["How much a Sentinel workspace costs","Which analysts closed the most incidents","When devices last installed updates","What a compromised entity can reach"],"answer":[3],"explanation":"Graph-based hunting maps relationships between users, devices, and resources, and blast radius analysis shows which critical assets an attacker could reach from a compromised entity."},{"id":"sc200-109","domain":"HNT","stem":"What does the Microsoft Sentinel graph help analysts explore?","options":["How entities relate across your data","Billing trends across Sentinel workspaces","Version history of analytics rules","The order in which playbooks were created"],"answer":[0],"explanation":"Sentinel graph models relationships among entities \u2014 identities, devices, resources, and activities \u2014 so analysts can explore connections and paths that are hard to see in tables."},{"id":"sc200-110","domain":"HNT","stem":"What are hunting queries in Microsoft Sentinel?","options":["Analytics rules that create incidents every minute","Saved queries for proactive threat searches","Playbooks that block IP addresses automatically","Workbooks that display cost by data source"],"answer":[1],"explanation":"Hunting queries are saved KQL queries, often mapped to MITRE ATT&CK, that analysts run to search for threats that haven\'t triggered alerts. Many are available from Content hub solutions."},{"id":"sc200-111","domain":"HNT","stem":"During a hunt, an analyst finds a suspicious result worth keeping for later investigation. What should they create?","options":["A summary rule","A device group","A bookmark","A data connector"],"answer":[2],"explanation":"Bookmarks save query results with notes and entity mappings so they can be revisited, added to incidents, or used to create new incidents."},{"id":"sc200-112","domain":"HNT","stem":"How can a hunter be alerted when a hunting query starts returning results?","options":["Export the query to a notebook","Pin the query to a Sentinel workbook","Turn it into an analytics rule","Add the query to a watchlist"],"answer":[2],"explanation":"If a hunting query proves useful, turning it into an analytics rule runs it on a schedule and creates alerts and incidents when it matches."},{"id":"sc200-113","domain":"HNT","stem":"What do KQL jobs in the Sentinel data lake do?","options":["Delete expired data from the analytics tier","Export analytics rules to another workspace","Promote lake query results to the analytics tier","Run playbooks automatically whenever an incident is created"],"answer":[2],"explanation":"KQL jobs run one-time or scheduled queries over data lake data and promote the results to a table in the analytics tier, where they can be used for detections and fast hunting."},{"id":"sc200-114","domain":"HNT","stem":"A hunter needs to search two years of DNS logs stored only in the data lake tier for a domain from a new threat report. What should they use?","options":["A near-real-time analytics rule","A KQL query or job on the lake","A live response session on a DNS server","A Defender for Endpoint indicator"],"answer":[1],"explanation":"Data lake exploration lets you run KQL directly over long-term lake data, and jobs can promote matching results to the analytics tier for further investigation."},{"id":"sc200-115","domain":"HNT","stem":"Why query a summary rule\'s output table instead of the raw verbose logs?","options":["It contains data the raw logs never included","It keeps data longer than any other table","It\'s the only table playbooks can read","It\'s smaller, so it\'s faster and cheaper"],"answer":[3],"explanation":"Summary rules pre-aggregate detailed data on a schedule into a compact table in the analytics tier, so repeated hunting queries and detections run faster and cost less."},{"id":"sc200-116","domain":"HNT","stem":"When would a hunter use a Jupyter notebook with the Sentinel data lake instead of KQL alone?","options":["For creating incidents from alerts every minute","For Python analysis, such as ML models","For assigning owners to new incidents","For deploying data connectors to many workspaces"],"answer":[1],"explanation":"Notebooks let hunters use Python libraries for advanced analytics, machine learning, and visualization over large data sets in the lake, and they can be scheduled."},{"id":"sc200-117","domain":"HNT","stem":"What does connecting to the Sentinel MCP server enable for hunting?","options":["AI agents querying Sentinel data via a standard protocol","Backup and restore of the Sentinel workspace configuration","Faster ingestion of Syslog data from Linux servers","Automatic creation of device groups in Defender for Endpoint"],"answer":[0],"explanation":"The Sentinel MCP (Model Context Protocol) server exposes Sentinel data and tools to MCP-compatible clients, such as AI agents and notebook environments, so they can explore security data in natural language or code."},{"id":"sc200-118","domain":"HNT","stem":"Which Advanced Hunting query finds devices where a specific file hash was seen?","options":["DeviceFileEvents | where SHA256 == \\"<hash>\\"","IdentityLogonEvents | where SHA256 == \\"<hash>\\"","EmailEvents | where SHA256 == \\"<hash>\\"","DeviceNetworkEvents | where SHA256 == \\"<hash>\\""],"answer":[0],"explanation":"DeviceFileEvents includes file hashes (SHA1 and SHA256) for file activity on devices. Email attachments\' hashes are in EmailAttachmentInfo, and logon and network tables don\'t record file hashes."},{"id":"sc200-119","domain":"HNT","stem":"Which KQL operator returns only selected columns, such as DeviceName and ProcessCommandLine?","options":["join","where","summarize","project"],"answer":[3],"explanation":"project chooses which columns to output (and can rename them). where filters rows, summarize aggregates, and join combines tables."},{"id":"sc200-120","domain":"HNT","stem":"A hunting query must find sign-ins from IP addresses on a watchlist named \\"BadIPs\\". Which approach works?","options":["Reference the watchlist in the data connector","Copy the IPs into the rule\'s MITRE mapping","Join the sign-in table with _GetWatchlist(\\"BadIPs\\")","Add the watchlist to the device group settings"],"answer":[2],"explanation":"_GetWatchlist returns the watchlist as a table, which can be joined or used with in() against sign-in data in hunting queries and analytics rules."},{"id":"sc200-121","domain":"HNT","stem":"Which Advanced Hunting table records authentication activity captured by Defender for Identity from on-premises Active Directory?","options":["CloudAppEvents","IdentityLogonEvents","EmailUrlInfo","DeviceProcessEvents"],"answer":[1],"explanation":"IdentityLogonEvents records authentication activity captured by Defender for Identity (on-premises AD) and Defender for Cloud Apps (online services). IdentityDirectoryEvents records directory changes."},{"id":"sc200-122","domain":"OPS","stem":"What does custom data collection in Microsoft Defender for Endpoint let a SOC do?","options":["Send all device data to a personal OneDrive account","Replace Defender for Endpoint with a third-party agent","Collect extra endpoint events using its own rules","Disable telemetry for devices in a chosen device group"],"answer":[2],"explanation":"Custom data collection rules let you collect additional endpoint telemetry beyond the default sensor data \u2014 for example, specific events needed for your detections \u2014 and send it to Advanced Hunting and Sentinel."},{"id":"sc200-123","domain":"OPS","stem":"Which Defender for Endpoint setting prevents malware or users from turning off Microsoft Defender Antivirus real-time protection?","options":["Web content filtering","Automated investigation","Tamper protection","Live response"],"answer":[2],"explanation":"Tamper protection locks Defender Antivirus security settings, such as real-time and cloud-delivered protection, so they can\'t be disabled through the registry, PowerShell, or Group Policy."},{"id":"sc200-124","domain":"INC","stem":"Defender for Cloud Apps detects a risky session downloading many files from SharePoint on an unmanaged device. Which control can block downloads in real time?","options":["An activity policy that emails the user weekly","A Conditional Access app control session policy","A Sentinel workbook showing download volumes","A file policy that runs once a day on stored files"],"answer":[1],"explanation":"Session policies, applied through Conditional Access app control, monitor and control activity within sessions as it happens, such as blocking downloads on unmanaged devices. Activity and file policies alert after the fact."},{"id":"sc200-125","domain":"INC","stem":"What are tasks in a Microsoft Sentinel incident used for?","options":["Defining which data connectors feed the workspace","Tracking the investigation steps analysts must complete","Scheduling analytics rules to run at specific times","Assigning Microsoft 365 licenses to analysts"],"answer":[1],"explanation":"Incident tasks are checklists of investigation and response steps, added manually or by automation rules and playbooks, so analysts follow consistent procedures."}]}')}}]);